from pathlib import Path
import json, html, shutil
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist'
DATA=json.loads((ROOT/'bank.json').read_text())
E=html.escape
BASE='https://omatty123.github.io/minds/'

def page(file,title,body):
 nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==file else '')+f'>{label}</a>' for p,label in [('index.html','Explore MIND'),('gallery.html','Post-it notes'),('proposal.html','The proposal'),('history.html','Global history'),('possibilities.html','Possibilities'),('syllabus.html','Model syllabus'),('bank.html','Learning bank'),('mind-words.html','Hear MIND'),('participate.html','Take part')])
 doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | MIND(s)</title><meta name="description" content="An interdisciplinary proposal for First-Year Studies: a model syllabus and a source-linked learning bank on minds, feeling, skill and consciousness."><meta name="theme-color" content="#151515"><link rel="canonical" href="{BASE+file}"><meta property="og:title" content="{E(title)} | MIND(s)"><meta property="og:description" content="An open faculty proposal. Explore the model syllabus and learning bank."><meta property="og:type" content="website"><meta property="og:image" content="{BASE}images/bangasayusang-share.jpg"><meta property="og:image:secure_url" content="{BASE}images/bangasayusang-share.jpg"><meta property="og:image:type" content="image/jpeg"><meta property="og:image:width" content="960"><meta property="og:image:height" content="1601"><meta property="og:image:alt" content="Bangasayusang — Korean Pensive Bodhisattva. National Museum of Korea, KOGL Type 1."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{BASE}images/bangasayusang-share.jpg"><meta name="twitter:image:alt" content="Bangasayusang — Korean Pensive Bodhisattva. National Museum of Korea."><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="fonts.css"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="masthead"><div class="mast-inner"><div class="brand-lockup"><a class="wordmark" href="index.html" aria-label="MIND(s) home">MIND<span>(s)</span></a><a class="heart-brand" href="mind-words.html#meanings" aria-label="심, sim: Korean reading of 心, heart and mind"><span lang="ko">심</span><span lang="ko-Hani">心</span></a></div><p>A proposal for<br class="brand-break"> First-Year Studies</p><span class="edition">Working edition<br>10 October 2026</span></div></header><nav class="nav" aria-label="Main navigation"><div>{nav}</div></nav><main id="main">{body}</main><footer><div><a class="footer-brand" href="index.html">MIND(s) <span class="heart-type" lang="ko">심 心</span></a><p>An independent faculty proposal for a future Lawrence University First-Year Studies theme.<br>Developed by Matty Wegehaupt. Not an adopted curriculum or institutional endorsement.</p></div><div class="footer-links"><a href="participate.html#editorial">Editorial standards</a><a href="https://github.com/omatty123/minds">Source &amp; revisions</a><a href="https://commons.wikimedia.org/wiki/File:Pensive_Bodhisattva_02.jpg">Share image: National Museum of Korea · KOGL Type 1</a><span>Research checked 10 October 2026</span></div></footer></body></html>'''
 (OUT/file).write_text(doc)

def ref(id,label=None):
 d=next(x for x in DATA if x['id']==id)
 return f'<a href="bank.html#{id}">{E(label or d["title"])}</a>'

def source(id):
 d=next(x for x in DATA if x['id']==id)
 return f'<a href="{E(d["url"])}">Original source</a>'

home='''<section class="opening"><div class="lead"><h1>What is a mind?</h1><p class="standfirst">A shared study of thinking, feeling, making, and being.</p><p>MIND(s) proposes a common first-year encounter with great works that examine mind across languages and cultures. It brings neuroscience into conversation with philosophy, Asian Studies, music, poetry, art, psychology, and sport.</p><p>Students would study minds through evidence, interpretation, and practice—and learn to write clearly about what remains unsettled.</p><div class="actions"><a class="button" href="syllabus.html">Read the model syllabus</a><a class="text-action" href="bank.html">Explore the learning bank <span aria-hidden="true">→</span></a><a class="text-action" href="history.html">Explore the global history <span aria-hidden="true">→</span></a><a class="text-action" href="possibilities.html">Explore campus possibilities <span aria-hidden="true">→</span></a></div></div><aside class="questions"><h2>The questions that begin it</h2><p>Why do we mind?</p><p>How do minds, sports, and art all interact?</p><p>What does it mean if we don’t know mind?</p><div class="status"><strong>Open for development</strong><span>A long-term proposal. An invitation to shape it.</span></div></aside></section>
<section class="front-section"><div class="section-heading"><h2>One theme. Many ways of knowing.</h2><a href="syllabus.html#sequence">See the ten-week sequence <span aria-hidden="true">→</span></a></div><div class="discipline-grid"><article><h3>Thinking &amp; feeling</h3><p>Neuroscience, philosophy and psychology distinguish attention, intelligence, affect and conscious experience. Students learn what each method can establish.</p></article><article><h3>Practice &amp; perception</h3><p>Asian Studies, sport and music bring trained action, cultivation, ensemble coordination and bodily experience into the center of the course.</p></article><article><h3>Form &amp; imagination</h3><p>Poetry and art develop their own accounts of experience. Close reading, listening and looking receive the same care as scientific interpretation.</p></article></div></section>
<section class="front-section"><div class="section-heading"><h2>Three starting points in current research</h2><a href="bank.html">Browse all sources <span aria-hidden="true">→</span></a></div><div class="research-leads">'''
for who,headline,desc,anchor in [('Michael Levin','Coordination beyond the brain','Cellular organization expands the study of cognition. The distinction between adaptive behavior and felt experience remains crucial.','levin-tissue'),('Mark Solms','Feeling at the center','An affect-centered account connects consciousness to bodily needs and uncertainty. Its extension to artificial agents is an active research claim.','solms-agent'),('Cameron Berg','Evidence from artificial systems','Mechanistic probes and model behavior make AI consciousness a concrete research problem. Self-report is a finding to examine, not a verdict.','berg-pain')]:
 home+=f'<article><h3>{who}</h3><h4><a href="bank.html#{anchor}">{headline}</a></h4><p>{desc}</p><a class="small-link" href="bank.html?researcher={who.replace(" ","+")}">Read the sources</a></article>'
home+='''</div><p class="editor-note">These are initial research priorities. The learning bank also includes competing theories, empirical tests, and cultural works. Inclusion does not imply agreement or endorsement.</p></section>
<section class="case-section"><div><h2>A liberal arts course about the minds doing the learning.</h2><p>The strongest case for MIND(s) is curricular: students can practice several kinds of inquiry on a shared subject that matters to their own intellectual lives.</p><p>A musician can bring the structure of a performance. An athlete can bring trained perception. A poet can bring an exact distinction that ordinary language misses. A scientist can bring a testable prediction. Each contribution changes the conversation.</p><p>The model centers sustained reading across Chinese, Buddhist, Islamic, European, African American and Japanese contexts, with a progression from summary through synthesis and revision. It treats disagreement as something to describe precisely.</p></div><aside><h3>A possible planning horizon</h3><p>Lawrence’s June 2024 announcement describes Water as a four-year theme beginning in fall 2024. The current <a href="https://inside.lawrence.edu/academics/academic-experience/first-year-studies/current-works">works page labels the theme 2024–27</a>. These public descriptions need clarification before proposing a transition date.</p><p>The transition date, proposal deadline and decision process still need confirmation.</p><a href="https://www.lawrence.edu/articles/water-initial-theme-first-year-studies-gets-makeover/">Read the institutional announcement</a></aside></section>
<section class="closing"><h2>Build something colleagues can teach together.</h2><p>The next step is to test the works, improve the sequence, and invite disciplinary expertise into the proposal.</p><a class="button" href="participate.html">Contribute to MIND(s)</a></section>'''
home=home.replace('<section class="front-section">', '<section class="front-section"><div class="section-heading"><h2>Hear words for mind.</h2><a href="mind-words.html">Explore the human-voice collection →</a></div><p>Languages connect thinking, feeling and understanding in different ways. Listen to individual speakers and compare the words. Explore <a href="mind-words.html#meanings">meaning clusters</a>, <a href="mind-words.html#signs">sign languages</a> and <a href="mind-words.html#symbols">visual representations of mind</a>.</p></section><section class="front-section">',1)
home=home.replace('<section class="front-section">', '<section class="front-section"><div class="section-heading"><h2>Before Gutenberg: directly pointing to mind</h2><a href="syllabus.html#jikji">Begin with Jikji →</a></div><p>The oldest surviving book printed with movable metal type is a book about mind. Printed in Korea in 1377, <em>Jikji</em> brings Buddhist teachings and the history of books directly into MIND(s). Its English title: <em>Essential Passages Pointing Directly to the Mind</em>.</p></section><section class="front-section">',1)
page('proposal.html','A shared study of minds',home)

SLATE=json.loads((ROOT/'slate.json').read_text())
slate_rows=''
for item in SLATE:
 links=' · '.join(ref(id) for id in item['sources'])
 slate_rows+=f'<article class="slate-work" id="slate-{item["id"]}"><div class="slate-meta">{E(item["weeks"])}<span>{E(item["form"])}</span></div><div><h3>{E(item["title"])}</h3><p>{E(item["entry"])}</p><p><strong>Intellectual reach.</strong> {E(item["depth"])}</p><details><summary>Proposed reading &amp; source</summary><p>{E(item["selection"])}</p><p>{links}</p></details></div></article>'
words=[
 ('English · historical','mind / gemynd','Memory and thought in the word’s Old English history. Present English includes remembering, attending and objecting.','word-mind'),
 ('Ancient Greek','noos / nous','Perception, thought and understanding. Distinguish this from psychē, the soul in Plato’s chariot passage.','word-nous'),
 ('Latin','mens','Mind, understanding and judgment; one relevant term among several, not a universal technical equivalent.','word-mens'),
 ('Sanskrit','manas','A term whose range includes thought, intention and feeling. Its technical sense changes with the philosophical school.','word-manas'),
 ('Pāli · Buddhist text','citta','The term in the Dhammapada’s Cittavagga. Read its cultivation within the verses’ ethical and religious setting.','dhammapada-mind'),
 ('Chinese · historical','心 · xīn','Heart and thinking are connected in the lexical record. “Heart-mind” keeps that overlap visible.','word-xin'),
 ('Arabic · a textual example','qalb / qulūb','Heart / hearts. Qur’an 22:46 connects hearts with reasoning; this example is not a complete Arabic vocabulary of mind.','word-qalb'),
 ('Korean · modern usage','마음 · maeum','Mind, heart, feeling and intention appear across the dictionary’s senses. This is modern usage, not a claim about ancient etymology.','word-maeum'),
 ('Japanese · modern usage','心 / こころ · kokoro','Mind, heart and spirit are contextual English glosses. A shared character with Chinese does not make usages identical.','word-kokoro')]
word_rows=''.join(f'<article class="word-row"><div><h4>{E(word)}</h4><span>{E(language)}</span></div><p>{E(note)} {ref(id,"Source")}</p></article>' for language,word,note,id in words)
pacing=[
 ('1–2','Zhuangzi','Open with Jikji’s title and its place in printing history. Begin the language comparison. Read the Inner Chapters and the short Egyptian and Greek companion sources. Return to practiced movement in Cook Ding.','Opening reflection; Summary at the end of week 2.'),
 ('3','Dhammapada','Read the verse collection; examine mental cultivation and liberation. Return to Jikji as a medieval Korean Buddhist companion, beginning with the translators’ introduction. A translation event can develop the distinctions among citta, manas and heart-mind.','Workbook and preparation for synthesis.'),
 ('4','Al-Ghazālī','Stay with the short autobiography, its doubt and its religious resolution. Bring its account of certainty into conversation with earlier works.','Develop a synthesis across two works.'),
 ('5','Descartes','Read the selected meditations with the intervening argument explained. Revisit Dickinson’s poems as another way of writing inward experience.','Synthesis at the end of week 5.'),
 ('6–7','Du Bois','Read the selected chapters, epigraphs and Sorrow Songs. Shared music, art and sport encounters make embodied and social experience part of the comparison.','Revise the synthesis using feedback.'),
 ('8','Kokoro · begin','Begin the full novel. Keep original-language terms available while developing an interpretation of another person’s inner life.','Revision of the Synthesis at the end of week 8.'),
 ('9–10','Kokoro · continue and complete','Complete the novel. A research event connects Solms, Levin and Berg with the course’s accumulated distinctions; the full papers remain extensions.','Final Synthesis and closing reflection at the end of term.')]
sequence=''.join(f'<article class="week"><div class="week-label">Week {w}</div><div><h3>{title}</h3><p>{body}</p><p class="writing"><strong>Writing:</strong> {writing}</p></div></article>' for w,title,body,writing in pacing)
syllabus=(ROOT/'syllabus-content.html').read_text().replace('{{SLATE}}',slate_rows).replace('{{WORDS}}',word_rows).replace('{{SEQUENCE}}',sequence)
page('syllabus.html','Model syllabus',syllabus)

def options(values):
 return ''.join(f'<option value="{E(x)}">{E(x)}</option>' for x in sorted(set(values)))
entries=''
for d in DATA:
 terms=' '.join([d['title'],d['author'],d['claim'],d['limit'],d['use'],*d['topics']])
 entries+=f'''<article class="bank-entry" id="{d['id']}" data-researcher="{E(d['focus'])}" data-kind="{E(d['kind'])}" data-topics="{E('|'.join(d['topics']))}" data-search="{E(terms.lower())}" data-date="{E(d['date'])}"><div class="entry-meta"><span class="evidence-type">{d['kind']}</span><span>{d['date']}</span>{'<span class="core-label">Shared work</span>' if d['core'] else ''}</div><div class="entry-body"><h2><a href="{E(d['url'])}">{E(d['title'])}</a></h2><p class="byline">{E(d['author'])}</p><p>{E(d['claim'])}</p><details><summary>Teaching use &amp; evidence notes</summary><div class="entry-notes"><p><strong>Teaching use</strong> {E(d['use'])}</p><p><strong>Limit</strong> {E(d['limit'])}</p><p><strong>Access</strong> {E(d['access'])}.</p><p><strong>Review depth</strong> {E(d['review'])}. Checked {d['checked']}.</p><div class="entry-links"><a href="{E(d['url'])}">Open source</a><a href="bank.html#{d['id']}">Link to this entry</a></div></div></details><p class="topics">{' · '.join(d['topics'])}</p></div></article>'''
bank=f'''<div class="page-title"><h1>Learning bank</h1><p class="standfirst">Research to examine. Works to teach. Claims to test.</p><p>A selected starting collection of {len(DATA)} sources, with particular attention to Levin, Solms and Berg. Recent research sits beside foundational studies and cultural works. Each entry identifies what it can—and cannot—support.</p></div><section class="bank-controls" aria-label="Filter sources" hidden><div class="search"><label for="search">Search the collection</label><input type="search" id="search" placeholder="Try attention, feeling, music…" autocomplete="off"></div><div class="filters"><label>Researcher<select id="researcher"><option value="">All researchers</option>{options(d['focus'] for d in DATA)}</select></label><label>Discipline<select id="discipline"><option value="">All disciplines</option>{options(t for d in DATA for t in d['topics'])}</select></label><label>Source type<select id="kind"><option value="">All source types</option>{options(d['kind'] for d in DATA)}</select></label><button type="button" id="reset">Clear filters</button></div></section><div class="bank-count"><p id="result-count" role="status" aria-live="polite">{len(DATA)} sources</p><a href="bank.json" download>Download source data (JSON)</a></div><p id="empty" hidden>No sources match these filters. Try a broader term or clear the filters.</p><div class="bank-list">{entries}</div><section class="bank-scope"><h2>Scope of this edition</h2><p>Checked 10 October 2026. The collection draws on the Levin Lab publication list, Reciprocal Research’s listed outputs, selected Solms papers, original publication records and institutional cultural resources. It is a selected reading bank, not a systematic review or a complete research inventory.</p><p>Publication status and evidence type are separate: a peer-reviewed theoretical paper still presents a theory. An abstract-level check is identified as such. A source’s date does not imply that it is the newest work in its field.</p><p>Priority gaps include recent research on music and sport, deeper review of the new multicultural slate, disability and neurodiversity scholarship, animal cognition, and a broader literary selection. Sources need deeper review and teaching trials before final adoption.</p><a href="participate.html#editorial">Read the editorial standards</a></section>'''
page('bank.html','Learning bank',bank)

participate='''<div class="page-title"><h1>Shape the proposal.</h1><p class="standfirst">A common course needs many kinds of expertise.</p><p>MIND(s) is an invitation to develop a teachable, interdisciplinary First-Year Studies theme. Colleagues can contribute a work, improve a research annotation, test a short unit, or help assess the proposed sequence.</p><a class="button" href="https://github.com/omatty123/minds/issues/new?title=Contribution%20to%20MIND(s)">Suggest a source or revision</a><p class="small">Submissions use public GitHub issues and require a GitHub account. Include a source link, a short rationale, and the proposed change. Please keep private correspondence and student information out of public submissions.</p></div><section><h2>Contributions that will move this forward</h2><div class="contribution-list"><article><h3>Recommend a teachable work</h3><p>Identify a specific text, artwork, recording or study. Give a manageable selection, an access route and a clear account of its contribution to the common course.</p></article><article><h3>Test a connection</h3><p>Develop a short comparison across two methods: musical timing and skilled movement, poetry and perception, cellular coordination and collective behavior, or cultivation and attention.</p></article><article><h3>Strengthen the evidence</h3><p>Add an important counterargument, a replication, a newer review or a clearer explanation of a study’s limits. Correct a record without treating disagreement as an error.</p></article></div></section><section class="case-section"><div><h2>Connections already available at Lawrence</h2><p><strong>Matty Wegehaupt’s translation of Hyecho’s pilgrimage account</strong> provides a direct scholarly contribution to this proposal. The <a href="https://hyecho-buddhist-pilgrim.asian.lsa.umich.edu/about.php">University of Michigan’s Hyecho’s Journey project</a> credits the 2012 translation volume for its journal quotations. A companion selection could examine observation, religious practice, translation and the limits of interpreting another person’s experience. <a href="bank.html#hyecho">Read the learning-bank entry</a>.</p><p>The <a href="https://lux.lawrence.edu/convocations/19/">2023 Catholic and Buddhist pilgrimage convocation by Madera Allan and Constance Kassor</a> offers a potential contribution through practice, movement, place and transformation. A MIND(s) unit could develop those connections while preserving the traditions’ histories and meanings.</p><p>Lawrence’s archive also includes <a href="https://lux.lawrence.edu/frst_lectures/112/">Madera Allan’s First-Year Studies lecture on Borges</a>. Literary treatments of memory and identity could strengthen a later syllabus revision.</p><p class="small">These are possible curricular connections drawn from public records. No participation or endorsement by the named faculty is implied.</p></div><aside><h3>Work in stages</h3><ol class="stages"><li><strong>Develop the case.</strong> Refine this syllabus and source bank with colleagues.</li><li><strong>Test a short unit.</strong> Gather evidence about reading load, accessibility and cross-disciplinary teaching.</li><li><strong>Confirm the process.</strong> Establish the actual theme-selection schedule, criteria and governance.</li><li><strong>Prepare the proposal.</strong> Submit a shared curriculum with works, access plans and teaching support.</li></ol></aside></section><section id="editorial"><h2>Editorial standards</h2><div class="two-col"><div><h3>Keep claims accountable</h3><p>Every research entry links a source and records its date, type, review depth and check date. Empirical observations, theoretical interpretations, preprints and cultural works retain their distinct roles.</p><p>We do not infer consciousness from complexity, successful performance or a model’s self-description alone. We also do not treat uncertainty as proof of absence. Competing accounts belong in the same collection.</p></div><div><h3>Keep the collection useful</h3><p>Teaching annotations identify a concrete use and a limit. Link to authorized texts and recordings. Preserve author names, translation context and the distinction between publication and endorsement.</p><p>This edition is manually curated. Its October 2026 check date is not an automatic updating service. Significant additions should receive a new check date and a revision note.</p></div></div></section><section class="closing"><h2>The first edition is a starting point.</h2><p>The purpose is to make the proposal specific enough to evaluate, teach from and improve.</p><a class="button" href="syllabus.html">Return to the model syllabus</a></section>'''
page('participate.html','Take part',participate)
shutil.copyfile(ROOT/'bank.json',OUT/'bank.json')
(OUT/'.nojekyll').touch()
(OUT/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#bd1622"/><text x="32" y="46" font-family="Arial,Helvetica,sans-serif" font-weight="bold" font-size="45" fill="white" text-anchor="middle">M</text></svg>')
